import{_ as a}from"./chunks/29.mN_qNvEw.js";import{_ as n}from"./chunks/2.BRgDBKom.js";import{_ as o,o as i,c as r,am as s}from"./chunks/framework.CenUaW7a.js";const c="/projects/AiMechaM1/en/advanced-kit/assets/38.CXwuTkif.png",t="/projects/AiMechaM1/en/advanced-kit/assets/39.CbDqnw_o.png",l="/projects/AiMechaM1/en/advanced-kit/assets/40.IIBgT1ZS.png",p="/projects/AiMechaM1/en/advanced-kit/assets/41.v96cLIKB.png",g="/projects/AiMechaM1/en/advanced-kit/assets/42.B7nqoX5a.png",d="/projects/AiMechaM1/en/advanced-kit/assets/43.B43VQgn-.png",h="/projects/AiMechaM1/en/advanced-kit/assets/44.k1PDG-UX.png",A=JSON.parse('{"title":"3.16 Lesson 16: Chassis and Robotic Arm Programming Practice","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.16 Lesson 16 Chassis and Robotic Arm Programming Practice.md","filePath":"docs/3. Course materials/3.16 Lesson 16 Chassis and Robotic Arm Programming Practice.md"}'),m={name:"docs/3. Course materials/3.16 Lesson 16 Chassis and Robotic Arm Programming Practice.md"};function u(b,e,f,w,y,v){return i(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-16-lesson-16-chassis-and-robotic-arm-programming-practice" tabindex="-1">3.16 Lesson 16: Chassis and Robotic Arm Programming Practice <a class="header-anchor" href="#_3-16-lesson-16-chassis-and-robotic-arm-programming-practice" aria-label="Permalink to &quot;3.16 Lesson 16: Chassis and Robotic Arm Programming Practice&quot;">​</a></h1><h2 id="_3-16-1-lesson-introduction" tabindex="-1">3.16.1 Lesson Introduction <a class="header-anchor" href="#_3-16-1-lesson-introduction" aria-label="Permalink to &quot;3.16.1 Lesson Introduction&quot;">​</a></h2><p>Building upon basic manipulation, precision grasping, and multi-level grasping from the previous three lessons, this fourth lesson in the robotic arm series incorporates the ultrasonic sensor to link perception with execution. Moving beyond manual button triggers, this lesson implements a fully automated workflow of ultrasonic distance measurement, Mecanum-wheel car approach, and automatic robotic arm grasping upon arrival, completing the transition from manual control to intelligent control.</p><p>Inspired by automated food assembly line picking, this lesson demonstrates the value of sensor integration. After reviewing ultrasonic ranging principles, four progressive tasks are set up to complete detection-driven movement, encapsulate angular functions, enable automatic grasping, and optimize anti-repeat grasping. The core project drives the Mecanum-wheel car to advance automatically based on distance measurement and complete grasping upon reaching the target range. Mastering ultrasonic programming, sensor-variable integration, conditional evaluation, and automated workflow design lays a solid foundation for line-following, obstacle avoidance, and vision recognition courses.</p><h2 id="_3-16-2-learning-objectives" tabindex="-1">3.16.2 Learning Objectives <a class="header-anchor" href="#_3-16-2-learning-objectives" aria-label="Permalink to &quot;3.16.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the distance measurement principle of the ultrasonic module. Master the hardware structure and I2C communication method of the ultrasonic sensor, and learn how to combine sensor data with variables in programming.</p><p><strong>2.</strong> Write programs to read the distance detected by the ultrasonic sensor and store it in a variable. Use conditional statements to control different movement modes of the Mecanum-wheel car based on ultrasonic distance values.</p><p><strong>3.</strong> Establish a closed-loop control mindset by understanding the complete control loop of sensor detection → controller decision-making → actuator execution → status feedback. Cultivate data-filtering awareness by recognizing that reading the ultrasonic sensor multiple times within a single cycle can cause inconsistent evaluations, whereas storing the reading in a variable resolves this issue.</p><p><strong>4.</strong> Connect ultrasonic ranging and robotic arm coordination technology to industrial scenarios such as smartphone screen assembly lines, food processing lines, and automated warehouse sorting.</p><h2 id="_3-16-3-preparation" tabindex="-1">3.16.3 Preparation <a class="header-anchor" href="#_3-16-3-preparation" aria-label="Permalink to &quot;3.16.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-wheel robot base × 1</li><li>Type-C USB data cable × 1</li><li>Computer running Windows or macOS × 1</li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running properly</li></ul><p><strong>Key Parameters and Layout Description:</strong></p><ul><li><p>Mount the ultrasonic sensor onto the Mecanum-wheel chassis at a height of approximately 8 cm and a width of approximately 6 cm.</p></li><li><p>Place the small target block in front of a &quot;black support block&quot; at a fixed position.</p></li><li><p>A stack of eight textbooks with an average thickness of 1 cm each can substitute for the &quot;black support block&quot;.</p></li><li><p>Grasping range: An ultrasonic detection distance between 10 cm and 15 cm represents the optimal grasping range.</p></li><li><p>Stopping threshold: The Mecanum-wheel car stops when the obstacle distance detected by the ultrasonic sensor is less than 25 cm.</p></li></ul><h2 id="_3-16-4-hands-on-project" tabindex="-1">3.16.4 Hands-On Project <a class="header-anchor" href="#_3-16-4-hands-on-project" aria-label="Permalink to &quot;3.16.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>Focusing on ultrasonic distance measurement, Mecanum-wheel car movement, and automatic robotic arm grasping, this program operates across a three-layer logic. Distance measurement data is cached in a variable for conditional evaluation, stopping the car to trigger grasping and synchronized sound-light feedback once the target range is reached. After grasping the object, the Mecanum-wheel car moves forward 5 cm to exit the trigger zone, forming a complete closed loop that prevents repeated grasping.</p><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Sensor reading</td><td style="text-align:center;"><img loading="lazy" height="74" width="462" src="'+c+'" class="common_img" style="width:300px;aspect-ratio:462 / 74;"></td><td style="text-align:left;">Reads the distance to an object ahead, measured by the ultrasonic sensor in centimeters, typically stored in a variable.</td></tr><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="53" width="534" src="'+a+'" class="common_img" style="width:300px;aspect-ratio:534 / 53;"></td><td style="text-align:left;">Controls the mechanical gripper to close for grasping a block or open for releasing a block.</td></tr><tr><td style="text-align:center;">Function encapsulation</td><td style="text-align:center;"><img loading="lazy" height="479" width="620" src="'+t+'" class="common_img" style="width:300px;aspect-ratio:620 / 479;"></td><td style="text-align:left;">Encapsulates the complete grasping and placing action sequences, including lowering, grasping or releasing, and lifting.</td></tr><tr><td style="text-align:center;">Sound and light feedback</td><td style="text-align:center;"><img loading="lazy" height="182" width="646" src="'+l+'" class="common_img" style="width:300px;aspect-ratio:646 / 182;"></td><td style="text-align:left;">Illuminates different light colors as status feedback when detecting obstacles or executing grasping actions.</td></tr><tr><td style="text-align:center;">Sound and light feedback</td><td style="text-align:center;"><img loading="lazy" height="72" width="661" src="'+p+'" class="common_img" style="width:300px;aspect-ratio:661 / 72;"></td><td style="text-align:left;">Emits prompt tones during key state transitions.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Programming Ultrasonic Obstacle Distance Detection and Mecanum-Wheel Car Movement</strong></p><ul><li><p>Define a <code>Distance</code> variable and assign the obstacle distance detected by the ultrasonic sensor to this variable.</p></li><li><p>Note: Reading the ultrasonic sensor directly multiple times during obstacle detection can lead to inconsistent evaluations, which is resolved by storing the reading in a variable.</p></li><li><p>Continuously update the value of the <code>Distance</code> variable inside the repeat forever loop.</p></li><li><p>Apply conditional evaluation: When <code>Distance</code> is greater than 25, drive the Mecanum-wheel car forward to approach the target. When <code>Distance</code> is less than or equal to 25, stop the Mecanum-wheel car.</p></li><li><p>Add ultrasonic RGB light changes as detection status feedback.</p></li></ul><img loading="lazy" height="744" width="692" src="'+g+'" class="common_img" style="width:300px;aspect-ratio:692 / 744;"><p><strong>Task 2: Tuning the Robotic Arm Lowering Angle to Align with the Small Block and Encapsulating Placing and Grasping Functions</strong></p><ul><li><p>Manually tune the angular positions of servo ID 2 and servo ID 3 so that the mechanical gripper reaches the exact grasping height of the small block.</p></li><li><p>Fine-tune the angles according to the actual physical setup to account for minor positional differences.</p></li><li><p>Define the <code>Robotic Arm Place</code> function: Extend the robotic arm forward → lower it to the grasping height → open the mechanical gripper → wait → raise the arm back to the initial position.</p></li><li><p>Define the <code>Robotic Arm Grab</code> function: Extend the robotic arm forward → lower it to the grasping height → close the mechanical gripper → wait until clamped firmly → raise the arm back to the initial position.</p></li><li><p>Initialize the robotic arm posture to the initial state.</p></li></ul><img loading="lazy" height="479" width="620" src="'+t+'" class="common_img" style="width:300px;aspect-ratio:620 / 479;"><p><strong>Task 3: Adding Grasping Code Blocks for Automatic In-Range Grasping</strong></p><ul><li><p>Add a branch to the conditional statement: When <code>Distance</code> is within the grasping range, call the <code>Gripper Grab</code> function.</p></li><li><p>Because the car remains within the grasping range, the loop triggers the grasping action repeatedly.</p></li><li><p>Trigger buzzer and RGB LED responses during grasping.</p></li></ul><img loading="lazy" height="844" width="597" src="'+d+'" class="common_img" style="width:300px;aspect-ratio:597 / 844;"><p><strong>Task 4: Resolving Repeated Grasping and Adding Ultrasonic RGB Light Responses</strong></p><ul><li><p>Optimize the logic: After the robotic arm completes grasping within the target range, drive the Mecanum-wheel car forward by 5 cm.</p></li><li><p>Moving forward 5 cm places the ultrasonic detection distance outside the 10 cm to 15 cm trigger interval, stopping the Mecanum-wheel car and preventing repeated grasping.</p></li><li><p>Add ultrasonic RGB light changes as status responses, illuminating one color during detection and another color during grasping.</p></li><li><p>Finally, integrate all tasks to achieve the complete automated workflow of ultrasonic detection → automatic approach → in-range grasping → forward movement to prevent repetition.</p></li></ul><img loading="lazy" height="1061" width="623" src="'+h+'" class="common_img" style="width:300px;aspect-ratio:623 / 1061;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Line Following and Obstacle Avoidance Switching</a>.</strong></p></div><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:600px;aspect-ratio:960 / 508;"><h2 id="_3-16-5-expansion-and-advancement" tabindex="-1">3.16.5 Expansion and Advancement <a class="header-anchor" href="#_3-16-5-expansion-and-advancement" aria-label="Permalink to &quot;3.16.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Ultrasonic Ranging and Height-Adaptive Grasping</strong></p><p>Add height-adaptive functionality to the basic automatic grasping program by placing target blocks on black support blocks of varying heights. Slowly lower the robotic arm from a high position while measuring distance with the ultrasonic sensor, recording the angle of servo ID 3 as the grasping height whenever a sudden distance change is detected before executing the grasp. Linking distance data with servo positions optimizes the search algorithm and illustrates autonomous three-dimensional environmental perception.</p><p><strong>Project 2: Multi-Target Sequential Automatic Grasping and Transport</strong></p><p>Design a multi-target automatic grasping system where the Mecanum-wheel car drives along a straight line to approach three equally spaced blocks sequentially, stopping automatically via ultrasonic ranging to grasp each block, transporting them to a unified placement area, and returning in a loop. Use a counter variable to record the number of grasped blocks and rely on movement distance to locate the next target, building a full-process state machine logic to practice decomposing and sequencing complex tasks.</p><h2 id="_3-16-6-q-a" tabindex="-1">3.16.6 Q&amp;A <a class="header-anchor" href="#_3-16-6-q-a" aria-label="Permalink to &quot;3.16.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: After the ultrasonic sensor measures the distance, what are the primary grasping parameters that must be tuned on the robotic arm, and why?</strong></p><p><strong>Answer</strong>: The core grasping parameters are the angular positions of servo ID 2 and servo ID 3. The ultrasonic sensor only controls the Mecanum-wheel car to stop at an appropriate horizontal distance and cannot determine whether the grasp succeeds. An incorrect height causes the gripper to pass over the object or collide with the ground, while an incorrect forward extension causes the gripper to fall short or push the object away. Both servo angles must be tuned accurately so that the mechanical gripper reaches the exact position of the object for a stable grasp.</p><p><strong>Q2: What is the purpose of adding wait time during the robotic arm grasping process?</strong></p><p><strong>Answer</strong>: Adding wait time ensures that the mechanical gripper clamps the object firmly and stably. After receiving a closing command, the bus servo requires physical time to complete its rotation and build sufficient clamping force on the gripper. Lifting the arm immediately without waiting easily causes the object to slip due to an incomplete grasp. Setting the wait duration slightly longer than the servo running time guarantees complete action execution and stabilizes the timing of the entire sequence, preventing consecutive actions from interfering with each other.</p><h2 id="_3-16-7-technical-support-and-discussion" tabindex="-1">3.16.7 Technical Support and Discussion <a class="header-anchor" href="#_3-16-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.16.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',50)])])}const P=o(m,[["render",u]]);export{A as __pageData,P as default};
